# CUDA kernel for optimized matrix multiplication with vectorization
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Global row and column indices
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int tile = 0; tile < numTiles; tile += UNROLL_FACTOR) {
        // Prefetch multiple tiles to hide memory latency
        for (int i = 0; i < UNROLL_FACTOR && (tile + i) < numTiles; i++) {
            // Load tile from A into shared memory
            int col_in_tile = (tile + i) * TILE_SIZE + tx;
            if (row < N && col_in_tile < N) {
                As[ty][tx] = A[row * N + col_in_tile];
            } else {
                As[ty][tx] = 0.0f;
            }

            // Load tile from B into shared memory
            int row_in_tile = (tile + i) * TILE_SIZE + ty;
            if (row_in_tile < N && col < N) {
                Bs[ty][tx] = B[row_in_tile * N + col];
            } else {
                Bs[ty][tx] = 0.0f;
            }

            __syncthreads();

            // Compute partial product for this tile
            for (int k = 0; k < TILE_SIZE; k++) {
                sum += As[ty][k] * Bs[k][tx];
            }

            __syncthreads();
        }
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input dimensions
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D tensors");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions incompatible for multiplication");

    int M = A.size(0);
    int N = A.size(1);
    int P = B.size(1);

    // Create output tensor
    auto C = torch::zeros({M, P}, A.options());

    // Set grid and block dimensions (32x8 for better occupancy)
    dim3 threadsPerBlock(32, 8);
    dim3 numBlocks((P + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (M + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch kernel
    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

