#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_ROWS 8
#define BLOCK_COLS 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Global row and column indices for the 4x4 tile
    int row = by * TILE_SIZE + ty * 4;
    int col = bx * TILE_SIZE + tx * 4;

    // Register accumulation
    float c[4][4] = {{0}};

    // Prefetch registers
    float a_reg[4];
    float b_reg[4];

    // Double buffering indices
    int buffer = 0;

    // Preload first tile
    for (int i = 0; i < 4; i++) {
        int load_row = ty * 4 + i;
        int load_col = tx;

        // Load A tile
        int A_idx = (by * TILE_SIZE + load_row) * N + load_col;
        if (by * TILE_SIZE + load_row < N && load_col < N) {
            As[buffer][load_row][load_col] = A[A_idx];
        } else {
            As[buffer][load_row][load_col] = 0.0f;
        }

        // Load B tile
        int B_idx = load_row * N + (bx * TILE_SIZE + tx);
        if (load_row < N && bx * TILE_SIZE + tx < N) {
            Bs[buffer][load_row][tx] = B[B_idx];
        } else {
            Bs[buffer][load_row][tx] = 0.0f;
        }
    }
    __syncthreads();

    // Loop over tiles
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; t++) {
        // Prefetch next tile
        int next_t = t + 1;
        if (next_t < numTiles) {
            for (int i = 0; i < 4; i++) {
                int load_row = ty * 4 + i;
                int load_col = next_t * TILE_SIZE + tx;

                // Prefetch A
                int A_idx = (by * TILE_SIZE + load_row) * N + load_col;
                if (by * TILE_SIZE + load_row < N && load_col < N) {
                    a_reg[i] = A[A_idx];
                } else {
                    a_reg[i] = 0.0f;
                }

                // Prefetch B
                int B_idx = load_col * N + (bx * TILE_SIZE + tx);
                if (load_col < N && bx * TILE_SIZE + tx < N) {
                    b_reg[i] = B[B_idx];
                } else {
                    b_reg[i] = 0.0f;
                }
            }
        }

        // Compute on current tile
        for (int k = 0; k < TILE_SIZE; k++) {
            // Load A values for this thread
            float a_val[4];
            for (int i = 0; i < 4; i++) {
                a_val[i] = As[buffer][ty * 4 + i][k];
            }

            // Load B values for this thread
            float b_val[4];
            for (int j = 0; j < 4; j++) {
                b_val[j] = Bs[buffer][k][tx * 4 + j];
            }

            // Accumulate
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    c[i][j] += a_val[i] * b_val[j];
                }
            }
        }

        // Switch buffer
        buffer = 1 - buffer;
        __syncthreads();

        // Store prefetched values to shared memory
        if (next_t < numTiles) {
            for (int i = 0; i < 4; i++) {
                int store_row = ty * 4 + i;
                int store_col = tx;

                As[buffer][store_row][store_col] = a_reg[i];
                Bs[buffer][store_row][tx] = b_reg[i];
            }
        }
        __syncthreads();
    }

    // Write result to global memory
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            int out_row = row + i;
            int out_col = col + j;
            if (out_row < N && out_col < N) {
                C[out_row * N + out_col] = c[i][j];
            }
        }
    }
}

